#include "symrep_bootstrap.hpp"
#include "staged_matrix.hpp"
using namespace symrep;
int main(int argc,char**argv){try{require(argc==2,"usage affine_TR_control_compare OUT");fs::path out=argv[1];auto started=std::chrono::steady_clock::now();rref_option_t opt;opt->pool.reset(1);auto old=read_matrix(out/"sew_masked_control_w6.wxf"),k=read_matrix(out/"SEW_4p2_affine_TR_control.wxf"),j=read_matrix(out/"suffix_TR92_to_TF175.wxf"),o=read_matrix(out/"affine_tail_w6_control_invariant_TF175_origin.wxf");PrivateCarrierChart chart(old);require(chart.complete,"oldkernelchart");size_t nf=1548;Mat embedded(k.nrow,nf*175),coordinates(k.nrow,old.nrow+1);for(size_t s=0;s<k.nrow;++s){for(auto[c,x]:k[s]){if(size_t(c)==nf*92){coordinates[s].push_back(index(old.nrow),x);for(size_t b=0;b<nf;++b)for(auto[t,y]:o[b])embedded[s].push_back(index(b*175+t),x*y);}else for(auto[t,y]:j[c%92])embedded[s].push_back(index((c/92)*175+t),x*y);}normalize(embedded[s]);for(size_t r=0;r<old.nrow;++r)if(auto v=embedded[s].find(chart.columns[r]))coordinates[s].push_back(index(r),*v/chart.values[r]);normalize(coordinates[s]);}
 Mat coeff(k.nrow,old.nrow);for(size_t r=0;r<coeff.nrow;++r)for(auto[c,x]:coordinates[r])if(size_t(c)<old.nrow)coeff[r].push_back(c,x);require(equal(mul(coeff,old),embedded),"TRlift violates independently solved fullTFspace");std::cout<<"OLD_TF_MEMBERSHIP pass seconds="<<seconds(started)<<std::endl;
 auto e=read_matrix(out/"lastpair_E.wxf");std::ifstream inp(out/"affine_tail_static.txt");size_t n;inp>>n;std::vector<I>piv(n),which(e.ncol,-1);for(size_t z=0;z<n;++z){size_t c;inp>>c;piv[z]=index(c-1);which[c-1]=index(z);}Mat ec(e.nrow,n);for(size_t r=0;r<e.nrow;++r)for(auto[c,x]:e[r])if(which[c]>=0)ec[r].push_back(which[c],x);for(auto&r:ec.rows)normalize(r);
 Mat reshaped(old.nrow*nf,175);for(size_t s=0;s<old.nrow;++s)for(auto[c,x]:old[s])reshaped[s*nf+c/175].push_back(index(c%175),x);old.clear();auto projected=mul(reshaped,ec);reshaped.clear();Mat eq(nf*n,coeff.ncol+1);for(size_t r=0;r<projected.nrow;++r)for(auto[c,x]:projected[r])eq[(r%nf)*n+c].push_back(index(r/nf),x);projected.clear();auto rhs=read_matrix(out/"affine_tail_w6_control_pivot_source.wxf");for(size_t r=0;r<nf;++r)for(auto[c,x]:rhs[r])eq[r*n+c].push_back(index(coeff.ncol),-x);require(mul(eq,transpose(coordinates)).nnz()==0,"TRkernel affine tail residual");std::cout<<"REFERENCE_SYSTEM rows="<<eq.nrow<<" cols="<<eq.ncol<<" nnz="<<eq.nnz()<<" seconds="<<seconds(started)<<std::endl;
 auto ref=kernel(eq,opt);require(ref.nrow==k.nrow,"referenceaffinedimension");Chart rc(ref,opt);auto change=rc.coordinates(coordinates);require(equal(mul(change,ref),coordinates)&&kernel(change,opt).nrow==0,"exactaffinekernelspaceequality");write(out/"affine_TR_control_reference_kernel.wxf",ref);write(out/"affine_TR_control_reference_change.wxf",change);std::ofstream z(out/"affine_TR_control_compare.json");z<<"{\"all_checks_pass\":true,\"old_full_TF_kernel_dimension\":282,\"augmented_affine_kernel_dimension\":"<<k.nrow<<",\"full_TF_membership\":true,\"exact_affine_tail_residual\":true,\"independent_complete_kernel_dimension_and_span\":true,\"seconds\":"<<seconds(started)<<",\"scope\":\"Weight6 control. Independently solved necessaryTF space restricted by all83affine local tail equations in every1548prefix coordinate. No predicted rank input.\"}\n";std::cout<<"COMPLETE exactspaceequality=pass dimension="<<k.nrow<<" seconds="<<seconds(started)<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
